	 ('d8787300-3237-481f-9c58-2ba633586311'::uuid,'5a1eb0a8-9ccf-4a4a-9101-7d6273ee5bb3'::uuid,'a0f4d588-d0d9-4c02-9f8f-258653f6522e'::uuid,'workflow','2025-08-27 13:08:53.165853','{"nodes": [{"data": {"desc": "", "selected": false, "title": "\u5f00\u59cb", "type": "start", "variables": [{"label": "query", "max_length": 999999, "options": [], "required": true, "type": "paragraph", "variable": "query"}, {"label": "ragflow_api_base", "max_length": 128, "options": [], "required": true, "type": "text-input", "variable": "ragflow_api_base"}, {"label": "ragflow_api_key", "max_length": 128, "options": [], "required": true, "type": "text-input", "variable": "ragflow_api_key"}, {"label": "kb_ids", "max_length": 999999, "options": [], "required": true, "type": "paragraph", "variable": "kb_ids"}, {"label": "top_k", "max_length": 48, "options": [], "required": false, "type": "number", "variable": "top_k"}, {"label": "page", "max_length": 48, "options": [], "required": false, "type": "number", "variable": "page"}, {"label": "page_size", "max_length": 48, "options": [], "required": false, "type": "number", "variable": "page_size"}, {"label": "similarity_threshold", "max_length": 48, "options": [], "required": false, "type": "number", "variable": "similarity_threshold"}, {"label": "vector_similarity_weight", "max_length": 48, "options": [], "required": false, "type": "number", "variable": "vector_similarity_weight"}]}, "height": 298, "id": "1745751056740", "position": {"x": 80, "y": 282}, "positionAbsolute": {"x": 80, "y": 282}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"code": "import re\nimport requests\n\ndef format_uuid(uuid_str):\n    if re.match(r''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'', uuid_str, re.I):\n        return uuid_str\n    uuid_str = re.sub(r''[^0-9a-f]'', '''', uuid_str.lower())\n    if len(uuid_str) != 32:\n        return uuid_str\n    formatted_uuid = f\"{uuid_str[0:8]}-{uuid_str[8:12]}-{uuid_str[12:16]}-{uuid_str[16:20]}-{uuid_str[20:32]}\"\n    return formatted_uuid\n\ndef convert_ragflow(ragflow, ragflow_api_base, ragflow_api_key):\n    result = []\n    code = ragflow[''code'']\n    if code == 0:\n        message = \"\"\n        position = 1\n\n        for chunk in ragflow[''data''][''chunks'']:\n            document_name = chunk.get(''document_keyword'', '''')\n            similarity = chunk.get(''similarity'', 0)\n            dataset_id = chunk.get(''dataset_id'', '''')\n            dataset_name = get_dataset_name(dataset_id, ragflow_api_base, ragflow_api_key)\n            formatted_dataset_id = format_uuid(dataset_id) if dataset_id else ''''\n\n            metadata = {\n                \"_source\": \"knowledge\",\n                \"dataset_id\": formatted_dataset_id,\n                \"dataset_name\": dataset_name,\n                \"document_name\": document_name,\n                \"data_source_type\": \"external\",\n                \"retriever_from\": \"workflow\",\n                \"score\": similarity,\n                \"position\": position\n            }\n\n            result_item = {\n                \"metadata\": metadata,\n                \"title\": document_name,\n                \"content\": chunk.get(''content'', '''')\n            }\n\n            result.append(result_item)\n            position += 1\n    else:\n        message = ragflow[''message'']\n    return {\n        \"result\": result,\n        \"code\": code,\n        \"message\": message,\n    }\n\ndef get_dataset_name(dataset_id, ragflow_api_base, ragflow_api_key):\n    url = f\"{ragflow_api_base}/api/v1/datasets?id={dataset_id}\"\n    headers = {\n        \"Authorization\": f\"Bearer {ragflow_api_key}\",\n    }\n    response = requests.get(url, headers=headers)\n    if response.status_code == 200:\n        data = response.json()\n        return data[''data''][0][''name'']\n\ndef main(query, ragflow_api_base, ragflow_api_key, kb_ids_str, similarity_threshold, vector_similarity_weight, top_k, page, page_size):\n    if not kb_ids_str:\n        raise ValueError(\"\u8bf7\u8f93\u5165\u77e5\u8bc6\u5e93ID\")\n    kb_ids = [kb_id.strip() for kb_id in kb_ids_str.split('','')]\n    data = {\n        \"similarity_threshold\": 0.2 if similarity_threshold is None else similarity_threshold,\n        \"vector_similarity_weight\": 0.3 if vector_similarity_weight is None else vector_similarity_weight,\n        \"rerank_id\": \"bge-reranker-v2-m3@Xinference\",\n        \"keyword\": False,\n        \"use_kg\": False,\n        \"question\": query,\n        \"top_k\": 256 if top_k is None else top_k,\n        \"document_ids\": [],\n        \"dataset_ids\": kb_ids,\n        \"page\": 1 if page is None else page,\n        \"page_size\": 10 if page_size is None else page_size\n    }\n    url = f\"{ragflow_api_base}/api/v1/retrieval\"\n    headers = {\n        \"Authorization\": f\"Bearer {ragflow_api_key}\",\n    }\n    response = requests.post(url, headers=headers, json=data)\n    if response.status_code == 200:\n        data = response.json()\n        return convert_ragflow(data, ragflow_api_base, ragflow_api_key)", "code_language": "python3", "desc": "", "outputs": {"code": {"children": null, "type": "number"}, "message": {"children": null, "type": "string"}, "result": {"children": null, "type": "array[object]"}}, "selected": false, "title": "\u4ee3\u7801\u6267\u884c", "type": "code", "variables": [{"value_selector": ["1745751056740", "query"], "variable": "query"}, {"value_selector": ["1745751056740", "ragflow_api_base"], "variable": "ragflow_api_base"}, {"value_selector": ["1745751056740", "ragflow_api_key"], "variable": "ragflow_api_key"}, {"value_selector": ["1745751056740", "kb_ids"], "variable": "kb_ids_str"}, {"value_selector": ["1745751056740", "similarity_threshold"], "variable": "similarity_threshold"}, {"value_selector": ["1745751056740", "vector_similarity_weight"], "variable": "vector_similarity_weight"}, {"value_selector": ["1745751056740", "top_k"], "variable": "top_k"}, {"value_selector": ["1745751056740", "page"], "variable": "page"}, {"value_selector": ["1745751056740", "page_size"], "variable": "page_size"}]}, "height": 54, "id": "1745751059702", "position": {"x": 388, "y": 282}, "positionAbsolute": {"x": 388, "y": 282}, "selected": true, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}, {"data": {"desc": "", "outputs": [{"value_selector": ["1745751059702", "result"], "variable": "result"}, {"value_selector": ["1745751059702", "code"], "variable": "code"}, {"value_selector": ["1745751059702", "message"], "variable": "message"}], "selected": false, "title": "\u7ed3\u675f", "type": "end"}, "height": 142, "id": "1745751062509", "position": {"x": 688, "y": 282}, "positionAbsolute": {"x": 688, "y": 282}, "selected": false, "sourcePosition": "right", "targetPosition": "left", "type": "custom", "width": 244}], "edges": [{"data": {"isInIteration": false, "isInLoop": false, "sourceType": "start", "targetType": "code"}, "id": "1745751056740-source-1745751059702-target", "source": "1745751056740", "sourceHandle": "source", "target": "1745751059702", "targetHandle": "target", "type": "custom", "zIndex": 0}, {"data": {"isInIteration": false, "isInLoop": false, "sourceType": "code", "targetType": "end"}, "id": "1745751059702-source-1745751062509-target", "source": "1745751059702", "sourceHandle": "source", "target": "1745751062509", "targetHandle": "target", "type": "custom", "zIndex": 0}], "viewport": {"x": 242, "y": 25, "zoom": 1}}','{"opening_statement": "", "suggested_questions": [], "suggested_questions_after_answer": {"enabled": false}, "text_to_speech": {"enabled": false, "language": "", "voice": ""}, "speech_to_text": {"enabled": false}, "retriever_resource": {"enabled": true}, "sensitive_word_avoidance": {"enabled": false}, "file_upload": {"image": {"enabled": false, "number_limits": 3, "transfer_methods": ["local_file", "remote_url"]}, "ena