-{uuid_str[12:16]}-{uuid_str[16:20]}-{uuid_str[20:32]}\"\n    return formatted_uuid\n\ndef convert_ragflow(ragflow, ragflow_api_base, ragflow_api_key):\n    result = []\n    code = ragflow[''code'']\n    if code == 0:\n        message = \"\"\n        position = 1\n\n        for chunk in ragflow[''data''][''chunks'']:\n            document_name = chunk.get(''document_keyword'', '''')\n            similarity = chunk.get(''similarity'', 0)\n            dataset_id = chunk.get(''dataset_id'', '''')\n            dataset_name = get_dataset_name(dataset_id, ragflow_api_base, ragflow_api_key)\n            formatted_dataset_id = format_uuid(dataset_id) if dataset_id else ''''\n\n            metadata = {\n                \"_source\": \"knowledge\",\n                \"dataset_id\": formatted_dataset_id,\n                \"dataset_name\": dataset_name,\n                \"document_name\": document_name,\n                \"data_source_type\": \"external\",\n                \"retriever_from\": \"workflow\",\n                \"score\": similarity,\n                \"position\": position\n            }\n\n            result_item = {\n                \"metadata\": metadata,\n                \"title\": document_name,\n                \"content\": chunk.get(''content'', '''')\n            }\n\n            result.append(result_item)\n            position += 1\n    else:\n        message = ragflow[''message'']\n    return {\n        \"result\": result,\n        \"code\": code,\n        \"message\": message,\n    }\n\ndef get_dataset_name(dataset_id, ragflow_api_base, ragflow_api_key):\n    url = f\"{ragflow_api_base}/api/v1/datasets?id={dataset_id}\"\n    headers = {\n        \"Authorization\": f\"Bearer {ragflow_api_key}\",\n    }\n    response = requests.get(url, headers=headers)\n    if response.status_code == 200:\n        data = response.json()\n        return data[''data''][0][''name'']\n\ndef main(query, ragflow_api_base, ragflow_api_key, kb_ids_str, similarity_threshold, vector_similarity_weight, top_k, page, page_size):\n    if not kb_ids_str:\n        raise ValueError(\"\u8bf7\u8f93\u5165\u77e5\u8bc6\u5e93ID\")\n    kb_ids = [kb_id.strip() for kb_id in kb_ids_str.split('','')]\n    data = {\n        \"similarity_threshold\": 0.2 if similarity_threshold is None else similarity_threshold,\n        \"vector_similarity_weight\": 0.3 if vector_similarity_weight is None else vector_similarity_weight,\n        \"rerank_id\": \"bge-reranker-v2-m3@Xinference\",\n        \"keyword\": False,\n        \"use_kg\": False,\n        \"question\": query,\n        \"top_k\": 256 if top_k is None else top_k,\n        \"document_ids\": [],\n        \"dataset_ids\": kb_ids,\n        \"page\": 1 if page is None else page,\n        \"page_size\": 10 if page_size is None else page_size\n    }\n    url = f\"{ragflow_api_base}/api/v1/retrieval\"\n    headers = {\n        \"Authorization\": f\"Bearer {ragflow_api_key}\",\n    }\n    response = requests.post(url, headers=headers, json=data)\n    if response.status_code == 200:\n        data = response.json()\n        return convert_ragflow(data, ragflow_api_base, ragflow_api_key)", "code_language": "python3", "desc": "", "outputs": {"code": {"children": null, "type": "number"}, "message": {"children": null, "type": "string"}, "result": {"children": null, "type": "array[object]"}}, "selected": false, "title": "\u4ee3\u7801\u6267\u884c", "type": "code", "variables": [{"value_selector": ["1745751056740", "query"], "variable": "query"}, {"value_selector": ["1745751056740", "ragflow_api_base"], "variable": "ragflow_api_base"}, {"value_selector": ["1745751056740", "ragflow_api_key"], "variable": "ragflow_api_key"}, {"value_selector": ["1745751056740", "kb_ids"], "variable": "kb_ids_str"}, {"value_selector": ["1745751056740", "similarity_threshold"], "variable": "similarity_threshold"}, {"value_selector": ["1745751056740", "vector_similarity_weight"], "variable": "vector_similarity_weight"}, {"value_selector": ["17457510567